package org.apache.commons.vfs2.filter;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.util.Objects;

import org.apache.commons.io.function.Uncheck;
import org.apache.commons.vfs2.FileObject;
import org.apache.commons.vfs2.FileSelectInfo;
import org.apache.commons.vfs2.VFS;
import org.junit.jupiter.api.Test;

/**
 * Tests for the {@link NameFileFilter} class.
 */
public class NameFileFilterTest1 {

    private FileSelectInfo createFileSelectInfo(final File file) {
        return Uncheck.get(() -> {
            final FileObject fileObject = VFS.getManager().toFileObject(file);
            return new FileSelectInfo() {
                @Override
                public FileObject getBaseFolder() {
                    return Uncheck.get(fileObject::getParent);
                }

                @Override
                public int getDepth() {
                    return 0;
                }

                @Override
                public FileObject getFile() {
                    return fileObject;
                }

                @Override
                public String toString() {
                    return Objects.toString(fileObject);
                }
            };
        });
    }

    @Test
    public void testAcceptName() throws Exception {
        final String fileName = "test-file.txt";
        final NameFileFilter filter = new NameFileFilter(fileName);

        // Test matching file
        final File matchingFile = new File(fileName);
        final FileSelectInfo matchingFileInfo = createFileSelectInfo(matchingFile);
        assertTrue(filter.accept(matchingFileInfo), "Filter should accept file with matching name.");

        // Test non-matching file name
        final File nonMatchingFile = new File("another-file.txt");
        final FileSelectInfo nonMatchingFileInfo = createFileSelectInfo(nonMatchingFile);
        assertFalse(filter.accept(nonMatchingFileInfo), "Filter should not accept file with different name.");

        // Test case-variant of non-matching name
        final File caseVariantFile = new File("Test-File.txt");
        final FileSelectInfo caseVariantInfo = createFileSelectInfo(caseVariantFile);
        assertFalse(filter.accept(caseVariantInfo), "Filter should not accept file with case-variant name by default.");

        // Test different extension
        final File diffExtFile = new File("test-file.log");
        final FileSelectInfo diffExtInfo = createFileSelectInfo(diffExtFile);
        assertFalse(filter.accept(diffExtInfo), "Filter should not accept file with different extension.");
    }

}

