    private FileSelectInfo createFileSelectInfo(final String name) throws FileSystemException {
        final FileObject fileObject = mock(FileObject.class);
        final FileName fileName = mock(FileName.class);
        when(fileObject.getName()).thenReturn(fileName);
        when(fileName.getBaseName()).thenReturn(name);
        final FileSelectInfo fileSelectInfo = mock(FileSelectInfo.class);
        when(fileSelectInfo.getFile()).thenReturn(fileObject);
        return fileSelectInfo;
    }

    @Test
    public void testNameFileFilter() throws FileSystemException {
        final NameFileFilter filter = new NameFileFilter(IOCase.SENSITIVE, "test2.txt");

        assertFalse(filter.accept(createFileSelectInfo("test1.txt")), "Filter should not accept 'test1.txt'");
        assertTrue(filter.accept(createFileSelectInfo("test2.txt")), "Filter should accept 'test2.txt'");
        assertFalse(filter.accept(createFileSelectInfo("Test2.txt")), "Filter should not accept 'Test2.txt' due to case sensitivity");
        assertFalse(filter.accept(createFileSelectInfo("test.xxx")), "Filter should not accept 'test.xxx'");
    }

