import java.nio.charset.StandardCharsets;

import org.apache.commons.vfs2.FileSystemOptions;
import org.junit.jupiter.api.Test;

/**
 * Tests {@link FtpFileSystemConfigBuilder}.
 */
public class FtpFileSystemConfigBuilderTest1 {

    /**
     * Tests that the control encoding can be configured as a charset or a string.
     */
    @Test
    public void testControlEncoding() {
        final FileSystemOptions opts = new FileSystemOptions();
        final FtpFileSystemConfigBuilder builder = FtpFileSystemConfigBuilder.getInstance();
        final Charset charset = StandardCharsets.UTF_8;
        final String charsetName = charset.name();

        // Test setting the encoding as a string
        builder.setControlEncoding(opts, charsetName);
        assertEquals(charset, builder.getControlEncodingCharset(opts));
        assertEquals(charsetName, builder.getControlEncodingCharset(opts).name());

        // Test setting the encoding as a charset
        builder.setControlEncoding(opts, charset);
        assertEquals(charset, builder.getControlEncodingCharset(opts));
        assertEquals(charsetName, builder.getControlEncodingCharset(opts).name());
    }
}

