package org.apache.commons.vfs2.provider.ftp;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.apache.commons.vfs2.FileObject;
import org.apache.commons.vfs2.FileSystemException;
import org.apache.commons.vfs2.impl.DefaultFileSystemManager;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * Tests for FTP file system with IPv6 link-local addresses.
 */
public class FtpFileSystemWithIPv6Test {

    private static DefaultFileSystemManager fsm;

    @BeforeAll
    public static void setUp() throws FileSystemException {
        fsm = new DefaultFileSystemManager();
        fsm.addProvider("ftp", new FtpFileProvider());
        fsm.init();
    }

    @AfterAll
    public static void tearDown() {
        if (fsm != null) {
            fsm.close();
        }
    }

    @Test
    public void testIPv6LinkLocalAddressResolution() throws FileSystemException {
        // As per RFC 2732 and RFC 4007, a link-local IPv6 address with a zone/scope ID should be formattable in a URI.
        final String ipv6HostWithScope = "[fe80::1:2:3:4%eth0]";
        final String resourcePath = "/remote-path/resource.txt";
        final String fullUri = "ftp://" + ipv6HostWithScope + resourcePath;
        // The root of this file system should have the host and a root path.
        final String rootUri = "ftp://" + ipv6HostWithScope + "/";

        // "request the system to locate and resolve this network resource"
        try (final FileObject resource = fsm.resolveFile(fullUri)) {

            // "verify that the underlying file system structure correctly recognizes and preserves the complete IPv6 address format
            // including the zone identifier in its root location identifier"
            assertEquals(rootUri, resource.getFileSystem().getRootURI());

            // "confirm that the individual resource reference itself maintains the identical address format"
            assertEquals(fullUri, resource.getName().getURI());
        }
        // "release any network connections or file system resources" - done by try-with-resources.
    }
}

