        if (tempDir.exists()) {
            assertTrue(tempDir.isDirectory() && ArrayUtils.isEmpty(tempDir.list()),
                    "Temp dir not empty before test (" + tempDir.getAbsolutePath() + ")");
        }

        manager = new DefaultFileSystemManager();
        manager.setFilesCache(providerConfig.getFilesCache());
        final DefaultFileReplicator replicator = new DefaultFileReplicator(tempDir);
        manager.setReplicator(new PrivilegedFileReplicator(replicator));
        manager.setTemporaryFileStore(replicator);
        providerConfig.prepare(manager);
        if (!manager.hasProvider("file")) {
            manager.addProvider("file", new DefaultLocalFileProvider());
        }
        manager.init();

        baseFolder = providerConfig.getBaseTestFolder(manager);
        if (baseFolder != null) {
            readFolder = baseFolder.resolveFile(READ_TESTS_FOLDER);
            writeFolder = baseFolder.resolveFile(WRITE_TESTS_FOLDER);
            assertTrue(readFolder.exists(), "Folder does not exist: " + readFolder);
            assertNotEquals(FileName.ROOT_PATH, readFolder.getName().getPath());
        }

        isSetUp = true;
    }

    @AfterEach
    public void tearDown() throws Exception {
        if (readFolder != null) {
            readFolder.close();
            readFolder = null;
        }
        if (writeFolder != null) {
            writeFolder.close();
            writeFolder = null;
        }
        if (baseFolder != null) {
            baseFolder.close();
            baseFolder = null;
        }
        if (manager != null) {
            manager.freeUnusedResources();
            manager.close();
            manager = null;
        }

        System.gc();
        Thread.sleep(1000L);
        System.gc();
        Thread.sleep(1000L);
        System.gc();
        Thread.sleep(1000L);
        System.gc();
        Thread.sleep(1000L);

        if (tempDir != null && tempDir.exists()) {
            assertTrue(tempDir.isDirectory() && ArrayUtils.isEmpty(tempDir.list()),
                    "Temp dir not empty after test (" + tempDir.getAbsolutePath() + ")");
        }

        VFS.close();
        Thread.sleep(20L);
    }

    @Test
    public void testResolveFile() throws FileSystemException {
        final FileName result = getManager().resolveURI("res:test-data");
        assertTrue(result.isFile());
    }

    @Override
    public DefaultFileSystemManager getManager() {
        return manager;
    }
